// Generated by scripts/build_test_gateway.py.
export default "<!doctype html><html><head><meta charset=\"utf-8\"><style>\n*{box-sizing:border-box}body{margin:0;background:#f4f7fa;color:#172c40;font:17px/1.55 Arial,sans-serif}main{max-width:790px;margin:36px auto;padding:32px;background:white;border-radius:12px}h1{font-size:30px;line-height:1.2;margin:8px 0 16px}h2{font-size:22px;margin-top:28px}label{display:block;font-weight:bold;margin-top:16px}input{width:100%;padding:12px;border:1px solid #8194a6;border-radius:5px;font:inherit}button,.download{background:#126573;color:white;border:0;border-radius:5px;padding:12px 18px;font:inherit;cursor:pointer;text-decoration:none;display:inline-block;margin:8px 6px 8px 0}button:disabled{opacity:.6;cursor:wait}.muted{color:#526577;font-size:15px}.error{color:#9f251e;font-weight:bold}li{margin:10px 0}.brand{font-size:14px;letter-spacing:1px;font-weight:bold;color:#526577}.download:focus,input:focus,button:focus{outline:3px solid #edab37;outline-offset:3px}[hidden]{display:none!important}@media(max-width:650px){main{margin:0;padding:22px;border-radius:0}h1{font-size:27px}.download{display:block;text-align:center}}\n</style></head><body><main>\n<div class=\"brand\">IUEA • PRACTICAL TEST</div><h1 id=\"heading\"></h1>\n<p>Get your test notebook and its data here. <strong>Double-check your full name, Student ID/ Registration Number, and email before clicking Start test.</strong> Use your own details and the same Google account throughout.</p>\n<div id=\"takehome\" hidden><p id=\"window\"></p><p><strong>Before starting: use a laptop, check your internet connection and sign in to the Google account you will enter below. Open this page in your normal browser, rather than inside WhatsApp.</strong> Clicking <strong>Start test</strong> starts your three hours immediately, including setup and submission. The class closing time is the final cutoff. The timer cannot be paused, including during internet interruptions. Refreshing or switching devices does not restart it. Opening this page alone does not start the timer. If you start less than three hours before the class cutoff, you have only the time remaining until that cutoff.</p></div>\n<form id=\"identity\"><label for=\"name\">Full name</label><input id=\"name\" autocomplete=\"name\" required maxlength=\"160\">\n<label for=\"email\">Google account email</label><input id=\"email\" type=\"email\" autocomplete=\"email\" required maxlength=\"254\"><div class=\"muted\">Use this account in Colab and on the final submission form.</div>\n<label for=\"registration\">Student ID/ Registration Number</label><input id=\"registration\" required maxlength=\"160\" autocomplete=\"off\"><div class=\"muted\">Enter your own number exactly as on your university record. Any format is accepted. When returning, use the same number as on your first visit; spaces and letter case do not matter.</div>\n<button id=\"get\" type=\"submit\">Get my test files</button><p class=\"muted\">Your email and registration number are recorded privately by your lecturer to assign and check your test files. Returning with the same details gives you the same files.</p></form>\n<p id=\"status\" role=\"status\" aria-live=\"polite\"></p>\n<section id=\"files\" hidden><h2>Your test is ready</h2><a id=\"colab\" class=\"download\" target=\"_blank\" rel=\"noopener\" hidden>Open my test in Colab</a><p id=\"timer\" role=\"status\"></p><p id=\"deadline\"></p><p id=\"downloadHelp\">Download both files to your laptop. Keep them together; do not use another student’s CSV.</p>\n<a id=\"notebook\" class=\"download\">1  Download test notebook</a><a id=\"csv\" class=\"download\">2  Download CSV data</a>\n<h2>Open and complete your test</h2><ol>\n<li id=\"accountStep\">Open <a href=\"https://colab.research.google.com/\" target=\"_blank\" rel=\"noopener\">Google Colab</a> on your laptop. Sign in with the Google email you entered above.</li>\n<li id=\"openStep\">Choose <strong>File → Open notebook → Upload</strong>. Select the downloaded <strong id=\"notebookLabel\"></strong>. Save a copy in Drive and work in that copy. Click <strong>Connect</strong> if shown.</li>\n<li id=\"dataStep\">Click the <strong>folder icon</strong> on the left, then <strong>Upload</strong> (upward arrow). Choose <strong>engineering_data.csv</strong> and wait until it appears. Uploading the notebook does not upload the CSV.</li>\n<li>Check your name, email and Student ID/ Registration Number near the top. Run cells using the triangle beside each code cell. Read the questions and work from top to bottom. Keep the requested answer names unchanged. Only Task 7 of Test 1 requires a function.</li></ol>\n<h2>Submit before the deadline</h2><ol>\n<li>Allow at least 20 minutes for submission. Save and run your completed cells. If the runtime was restarted, run the supplied setup cell again (or upload your assigned CSV for a manually loaded notebook). Check your work. Submit completed work even if some tasks remain unfinished.</li>\n<li>Run the final submission cell. Select your own Google account and review the access prompt. Click <strong>Submit test</strong> and wait for its form link.</li>\n<li>Open that link using the same Google account. If another email is shown, select Switch account and choose your own. Check your full name and Student ID/ Registration Number. Leave the automatically filled test allocation code and snapshot fields unchanged. Tick the email confirmation box and press <strong>Submit</strong>.</li>\n<li>Wait for the form confirmation. Keep the saved snapshot unchanged in Drive until marks are released.</li></ol>\n<p><strong>The notebook button alone does not finish submission. You must also submit the form.</strong></p>\n<p>No manual notebook download and re-upload is needed for submission. If anything fails, note the error and contact your lecturer immediately, before your deadline. A connection problem does not pause or extend the timer. Do not use AI-generated solutions, messaging or copied answers.</p>\n<a id=\"instructions\" download=\"Test_instructions.txt\">Download these test instructions</a>\n<p class=\"muted\">If you scan the QR code on a phone, open this same page on your laptop and enter the same details. Start only when you are ready to work on a laptop. Refreshing the page does not change your allocation.</p>\n</section></main><script>\nconst testKey=__TEST_KEY_JSON__;\ndocument.getElementById('heading').textContent=testKey.replace('|TEST',' — Test ');\nlet timerInterval;\nasync function getFiles(success,failure,input){\n try {\n  const response=await fetch('/api/files',{method:'POST',headers:{'Content-Type':'application/json'},credentials:'omit',cache:'no-store',body:JSON.stringify(input)});\n  const result=await response.json();\n  if(!response.ok||!result.ok)throw Error(result.error||'Could not prepare files. Tell your lecturer.');\n  success(result.result);\n } catch(error){failure(error);}\n}\nlet objectUrls=[];\nconst windows={\n 'CML3111|TEST1':'24 October 2026, 11:00 AM – 29 October 2026, 11:59 PM',\n 'CML3113|TEST1':'24 October 2026, 11:00 AM – 29 October 2026, 11:59 PM',\n 'CML3112|TEST1':'27 October 2026, 7:00 PM – 2 November 2026, 11:59 PM'\n};\nif(windows[testKey]){document.getElementById('takehome').hidden=false;document.getElementById('window').textContent='Available: '+windows[testKey]+' (Kampala time).';document.getElementById('get').textContent='Start test / Resume my test';}\nfunction showTimed(result){\n clearInterval(timerInterval);\n if(!result.personalDeadline)return;\n const direct=document.getElementById('colab');direct.href=result.colabUrl;direct.hidden=!result.colabUrl;direct.textContent=result.workingMode==='DIRECT'?(result.resumed?'Resume my test in Colab':'Open my test in Colab'):'Open issued original (not your saved answers)';\n document.getElementById('downloadHelp').textContent='Use Open my test in Colab. The downloads below are a backup; your CSV is included in the setup cell.';\n document.getElementById('accountStep').textContent='Use the same Google account you entered above. If Google shows another account, use its account selector to choose yours.';\n document.getElementById('notebook').textContent='Backup notebook download';\n document.getElementById('csv').textContent='Backup CSV download';\n document.getElementById('openStep').textContent='Click Open my test in Colab above. Sign in with the same Google account, then choose File → Save a copy in Drive. Work in your saved copy, not the read-only original. Click Connect if shown. To resume later, reopen your saved copy from Google Drive; the entry page opens the original test, not your answers.';\n if(result.workingMode==='DIRECT'){document.getElementById('openStep').textContent='Click '+direct.textContent+' above. Work in this private editable notebook; no separate copy is needed. Save regularly with File → Save. After a closed tab, disconnection or shutdown, return to this page with the same email and registration number and click Resume. Only work saved before the interruption can be recovered.';}else{document.getElementById('openStep').textContent='If you already worked in a saved copy, reopen that copy from Google Drive or Colab Recent notebooks. The original link above does not contain those answers. For a first start with this older file, use File → Save a copy in Drive.';}\n document.getElementById('dataStep').textContent='Run Check details and countdown near the top (if present), then Prepare CSV and libraries. This creates engineering_data.csv automatically. For Test 1, write your own pandas code to read it into raw_data in Task 1. Rerun the countdown and setup after a runtime reset. The countdown does not pause or extend your deadline; older copies without it can use the timer on this page.';\n const offset=Date.parse(result.serverNow)-Date.now();\n const tick=()=>{const left=Math.max(0,Date.parse(result.personalDeadline)-(Date.now()+offset)),seconds=Math.ceil(left/1000);document.getElementById('timer').textContent=left?'Time remaining: '+Math.floor(seconds/3600)+'h '+Math.floor(seconds%3600/60)+'m '+seconds%60+'s. Finish the submission form before time runs out.':'Your test time has ended. Late submissions are not accepted for grading.';};\n tick();timerInterval=setInterval(tick,1000);\n}\n\nfunction download(id,text,type,name){const el=document.getElementById(id),url=URL.createObjectURL(new Blob([text],{type}));objectUrls.push(url);el.href=url;el.download=name;}\ndocument.getElementById('identity').addEventListener('submit',e=>{e.preventDefault();const button=document.getElementById('get'),status=document.getElementById('status');button.disabled=true;status.className='';status.textContent='Preparing your files…';document.getElementById('files').hidden=true;\nconst input={test:testKey,name:document.getElementById('name').value,email:document.getElementById('email').value,registration:document.getElementById('registration').value};\ngetFiles(result=>{objectUrls.forEach(URL.revokeObjectURL);objectUrls=[];download('notebook',result.notebook,'application/x-ipynb+json',result.notebookName);download('csv',result.csv,'text/csv',result.csvName);download('instructions',result.instructions,'text/plain','Test_instructions.txt');const notebookLabel=document.getElementById('notebookLabel');if(notebookLabel)notebookLabel.textContent=result.notebookName;document.getElementById('deadline').textContent='Submission closes: '+result.deadline;document.getElementById('files').hidden=false;showTimed(result);status.textContent=result.personalDeadline?'Your timer is running. Open your notebook in Colab below.':'Files ready. Download the notebook and CSV below.';button.disabled=false;document.getElementById('files').scrollIntoView({behavior:'smooth'});},err=>{status.className='error';status.textContent=err.message||'Could not prepare files. Tell your lecturer.';button.disabled=false;},input);\n});\n</script></body></html>\n";
